style.css:
@-moz-document domain("youtube.com") {
/* Progress bar */
    .html5-video-player .ytp-play-progress {
        background: #7A1024 !important;
    }

    /* Pucca GIF scrubber */
    .html5-video-player .ytp-scrubber-button {
        width: 52px !important;
        height: 52px !important;
        background: url("https://www.image2url.com/r2/default/gifs/1785056186499-0187652d-3f97-42c2-b19d-839abb8145b0.gif") center/contain no-repeat !important;
        background-color: transparent !important;
        border: none !important;
        border-radius: 0 !important;
        box-shadow: none !important;
        margin-left: -19px !important;
        margin-top: -29px !important;
    }

    .html5-video-player .ytp-scrubber-button::before,
    .html5-video-player .ytp-scrubber-button::after {
        display: none !important;
        content: none !important;
    }
}
